"""Finite real-contact presentation integration check; no replay framework."""
from pathlib import Path
import os,json,hashlib
from playwright.sync_api import sync_playwright
R=Path(__file__).resolve().parents[2];O=R/'qa/eight-fighters';O.mkdir(parents=True,exist_ok=True);html=(R/'dist/INK-Street-Fighter-6.html').read_bytes()
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path=os.environ['INK_CHROMIUM'],headless=True);p=b.new_page();errors=[];p.on('pageerror',lambda e:errors.append(str(e)));p.set_content(html.decode());p.wait_for_function('window.INKDuel?.ready')
 rows=p.evaluate('''()=>{const A=SVG_FIGHTER,G=A.state,C=INK.ContactResponse,K=INK.Kinetic,F=INK.ImpactFeedback,S=INK.StrikeFeel,out=[],check=(name,passed,details)=>out.push({name,passed,details});
 const cases=[['normal','luke',m=>m.id==='sHP',180],['special','mai',m=>m.category==='special'&&m.kind==='rush'&&!m.od,180],['projectile','ryu',m=>m.category==='special'&&m.kind==='projectile'&&!m.od,420],['multi','chun',m=>m.category==='special'&&m.kind==='barrage'&&!m.od&&m.hits>1,180],['throw','iori',m=>m.id==='throw',100]];
 function run(id,m,distance,enabled){A.start(id,'ryu','training','classic',7);G.paused=true;document.getElementById('dummy').value='idle';document.getElementById('infinite').checked=false;document.getElementById('autohp').checked=false;C.settings.enabled=enabled;K.clear();F.clear();S.clear();A.teleport(0,450);A.teleport(1,450+distance);A.step();A.inputMove(0,m.id);let seen=[],trace=[],maxVisible=0,maxPerBody=0;for(let i=0;i<180;i++){A.step();const d=A.fighters[1];trace.push([d.hp,d.x,d.y,d.vx,d.vy,d.push,d.state,d.stateT]);const visible=K.visibleContacts(G);maxVisible=Math.max(maxVisible,visible.length);for(const e of visible)maxPerBody=Math.max(maxPerBody,visible.filter(v=>v.defender===e.defender&&v.type!=='landing').length);const k=K.inspect().events.filter(e=>e.move===m.id).at(-1);if(k&&!seen.some(e=>e.id===k.id)){const fx=F.events.filter(e=>e.move===m.id).at(-1),audio=S.inspect().filter(e=>e.move===m.id).at(-1);seen.push({id:k.id,contact:k.contact,point:[k.x,k.y],fx:fx?{response:fx.response,multi:fx.multi}:null,audio});}}return {seen,trace,maxVisible,maxPerBody,counts:{kinetic:K.inspect().events.length,fx:F.events.length,audio:S.inspect().length}};}
 for(const [kind,id,choose,distance] of cases){const m=A.moves[id].find(choose);if(!m){check(kind+' fixture exists',false);continue;}const baseline=run(id,m,distance,false),r=run(id,m,distance,true);const propagated=r.seen.length>0&&r.seen.every(e=>e.contact&&e.fx?.response&&JSON.stringify(e.contact)===JSON.stringify(e.fx.response)&&e.audio?.style===e.contact.style&&e.audio.part===e.contact.part&&e.point.every((v,i)=>v===e.contact.point[i]));check(kind+' actual contact unifies body FX and audio',propagated,{character:id,move:m.id,events:r.seen});if(kind!=='normal')check(kind+' leaves authored push damage and trajectories unchanged',r.seen.every(e=>e.contact?.affectsPush===false)&&JSON.stringify(r.trace)===JSON.stringify(baseline.trace),{contacts:r.seen.length});check(kind+' visual composition and event histories stay bounded',r.maxPerBody<=2&&r.maxVisible<=8&&r.counts.kinetic<=40&&r.counts.fx<=128&&r.counts.audio<=32,{maxPerBody:r.maxPerBody,maxVisible:r.maxVisible,counts:r.counts});if(kind==='multi')check('multi makes multiple actual contacts with intermediate presentation',r.seen.length>1&&r.seen.some(e=>e.contact?.multi),{contacts:r.seen.length});}
 C.settings.enabled=true;return out;}''');b.close()
for r in rows:print('PASS' if r['passed'] else 'FAIL',r['name'])
(O/'presentation.json').write_text(json.dumps({'htmlSha256':hashlib.sha256(html).hexdigest(),'rows':rows,'errors':errors},indent=2)+'\n');print(errors);assert all(r['passed'] for r in rows) and not errors
